events.conditionSnippet:
show: s => {
        const a = s.lifeRecord?.affiliations?.find(x => x.id === "ursus-kleini-sever-mine");
        return (
          !!a &&
          ["active", "crisis", "suspended"].includes(a.status) &&
          Number.isInteger(a.startedYear) &&
          s.year >= a.startedYear + 2
        );
      },
      st: ["青年", "壮年", "老年"],
      once: true,
      w: 0.5,
      t: "監視付きの採掘班に送り込まれて二年が過ぎた。皮下に埋め込まれた位置特定チップを抜き取ろうと、密かに外の医療班とつなぎを取る坑夫もいる。信号が途絶えれば爆発するぞという監視隊の脅しが耳にこびりつき、見回りの軍靴が近づくたび皮膚の下が疼く気がした。",

show: s => !!$rules.social.institutionalInfectionAudience(s),
      w: 0.8,
      cd: 6,
      t: [
        {
          when: "就労中",
          t: "地区の役所から、診断記録を根拠に隔離区画へ移るよう通達が届いた。移れば仕事を失うことになり、当面の収入も途絶える。"
        },
        {
          t: "地区の役所から、診断記録を根拠に隔離区画へ移るよう通達が届いた。移れば外での自由を奪われ、狭い区画に押し込められることになる。"
        }
      ],

show: s =>
        s.siracusaFamilyTie?.status === "left" &&
        !s.lifeRecord?.affiliations?.some(
          row => row.id === "siracusa-post-family-work" && row.status === "active"
        ),
      once: true,
      w: 0.72,
      t: [
        {
          when: s => Number(s.siracusaFamilyTie?.duty?.outstandingAmount) > 0,
          t: "ファミリーの仕事から手を引いた。帳面に残った立替金はまだ片づかず、別の働き口を探す必要がある。地区の掲示で配達と露店の求人を見つけた。"
        },
        {
          t: "ファミリーの仕事を終え、次の稼ぎ口を探した。地区の掲示には近距離の配達と露店の手伝いが出ていた。"
        }
      ],

show: s => {
        const service = s.lifeRecord?.affiliations?.find(row => row.id === "higashi-service");
        return (
          s.age >= 50 &&
          service?.status === "active" &&
          Number.isInteger(service.startedYear) &&
          s.year - service.startedYear >= 15
        );
      },
      once: true,
      w: 0.85,
      t: "気づけば十五年以上も軍務・兵站の現場に身を置き、急な陣触れと家の暮らしのあいだで折り合いをつけてきた。このまま古参として部隊に残るか、培った街道と荷捌きの知識を民間へ移すか、あるいはいったん荷を下ろすか思案した。",

show: s => !!s.world?.events?.kazdel_civil_war,
      ge: { year: 1092 },
      le: { year: 1094 },
      once: true,
      w: 0.8,
      cd: 5,
      who: s => (s.age < $rules.parameters.value("life.adultStartAge") ? "parent" : "self"),
      t: [
        {
          when: "未成年",
          t: "カズデル全土に内戦の炎が広がり、大人たちは国を捨てるか残るかで夜通し言い争っている。あなたは押し殺した声に耳を澄ませながら、いつでも逃げられるよう荷物をまとめた。"
        },
        {
          t: "内戦の戦火がいよいよ身近に迫り、故郷を捨てて国境を越えるか、この地に留まるか決断を迫られた。逃げ道も荒野も、どちらも血と硝煙の匂いがしていた。"
        }
      ],
